const items={"bounce": {"label": "开心小弹 · 最终透明候选", "note": "表演沿用你已确认的双爪贴地小弹，107帧与原速保持；仅恢复3970个眼内误透明点，右袖与斗篷之间真实窄缝保留。黑／灰／白底可切换，下方为无损PNG。白底掌底与白毛尖仍有细暗紫及少量灰绿暗粒，帽沿和袖缝旁也可能看到细彩边；原始低alpha边缘RGB有亮黄绿，正常合成可见度更低。本次只确认最终透明细节，未进入正式资源；你给出评审结果后关闭服务器。"}},movie=document.querySelector('#movie');let active=Object.keys(items)[0],matte='black';
for(const [id,item]of Object.entries(items)){const b=document.createElement('button');b.textContent=item.label;b.dataset.id=id;b.onclick=()=>select(id);document.querySelector('#actions').append(b)}
function updateFrame(){const i=document.querySelector('#slider').value;document.querySelector('#frames').src='/frame.png?id='+encodeURIComponent(active)+'&i='+i;document.querySelector('#frameLabel').textContent=String(i).padStart(3,'0')+' / 106'}
function select(id){movie.pause();active=id;document.querySelector('#reference').src='/reference.png?id='+encodeURIComponent(id);document.querySelector('#name').textContent=items[id].label;document.querySelector('#note').textContent=items[id].note;document.querySelector('#caption').textContent=items[id].label+' · 完整原速循环 · 1×';for(const b of document.querySelectorAll('[data-id]'))b.classList.toggle('active',b.dataset.id===id);document.querySelector('#slider').value=0;updateFrame();movie.src='/video.mp4?id='+encodeURIComponent(id)+'&bg='+matte;movie.play().catch(()=>{})}
function background(name,color){const time=movie.currentTime,paused=movie.paused;matte=name;document.documentElement.style.setProperty('--matte',color);movie.src='/video.mp4?id='+encodeURIComponent(active)+'&bg='+name;movie.addEventListener('loadedmetadata',()=>{movie.currentTime=Math.min(time,movie.duration||time);if(!paused)movie.play().catch(()=>{})},{once:true})}
function restart(){movie.currentTime=0;movie.play().catch(()=>{})}function toggle(){movie.paused?movie.play().catch(()=>{}):movie.pause()}function frame(){movie.pause();updateFrame()}movie.addEventListener('ratechange',()=>{if(movie.playbackRate!==1)movie.playbackRate=1});const initial=decodeURIComponent(location.hash.slice(1));select(items[initial]?initial:active);